-- unset /api/v1/lineup/net-requirement 51691.7 ms
-- params: {"coalesce_2": 0, "coalesce_4": 0, "tid_1": "default", "coalesce_5": 0, "coalesce_6": 0, "lower_1": "shipped"}
SELECT inv_latest.distributor_id, inv_latest.product_id, inv_latest.snapshot_date, inv_latest.on_hand_units, coalesce(sell_since.sell_out, %(coalesce_2)s::INTEGER) AS coalesce_1, coalesce(land_since.landed, %(coalesce_4)s::INTEGER) AS coalesce_3 
FROM (SELECT fact_inventory_distributor.distributor_id AS distributor_id, fact_inventory_distributor.product_id AS product_id, fact_inventory_distributor.as_of_date AS snapshot_date, fact_inventory_distributor.on_hand_units AS on_hand_units 
FROM fact_inventory_distributor JOIN (SELECT fact_inventory_distributor.distributor_id AS distributor_id, fact_inventory_distributor.product_id AS product_id, max(fact_inventory_distributor.as_of_date) AS snapshot_date 
FROM fact_inventory_distributor 
WHERE fact_inventory_distributor.tenant_id = %(tid_1)s::VARCHAR GROUP BY fact_inventory_distributor.distributor_id, fact_inventory_distributor.product_id) AS anon_1 ON fact_inventory_distributor.distributor_id = anon_1.distributor_id AND fact_inventory_distributor.product_id = anon_1.product_id AND fact_inventory_distributor.as_of_date = anon_1.snapshot_date 
WHERE fact_inventory_distributor.tenant_id = %(tid_1)s::VARCHAR) AS inv_latest LEFT OUTER JOIN (SELECT fact_sales_sellout.distributor_id AS distributor_id, fact_sales_sellout.product_id AS product_id, coalesce(sum(fact_sales_sellout.units), %(coalesce_5)s::INTEGER) AS sell_out 
FROM fact_sales_sellout JOIN (SELECT fact_inventory_distributor.distributor_id AS distributor_id, fact_inventory_distributor.product_id AS product_id, max(fact_inventory_distributor.as_of_date) AS snapshot_date 
FROM fact_inventory_distributor 
WHERE fact_inventory_distributor.tenant_id = %(tid_1)s::VARCHAR GROUP BY fact_inventory_distributor.distributor_id, fact_inventory_distributor.product_id) AS anon_1 ON fact_sales_sellout.distributor_id = anon_1.distributor_id AND fact_sales_sellout.product_id = anon_1.product_id AND fact_sales_sellout.transaction_date > anon_1.snapshot_date 
WHERE fact_sales_sellout.tenant_id = %(tid_1)s::VARCHAR GROUP BY fact_sales_sellout.distributor_id, fact_sales_sellout.product_id) AS sell_since ON sell_since.distributor_id = inv_latest.distributor_id AND sell_since.product_id = inv_latest.product_id LEFT OUTER JOIN (SELECT fact_inbound_shipment.distributor_id AS distributor_id, fact_inbound_shipment.product_id AS product_id, coalesce(sum(fact_inbound_shipment.quantity), %(coalesce_6)s::INTEGER) AS landed 
FROM fact_inbound_shipment JOIN (SELECT fact_inventory_distributor.distributor_id AS distributor_id, fact_inventory_distributor.product_id AS product_id, max(fact_inventory_distributor.as_of_date) AS snapshot_date 
FROM fact_inventory_distributor 
WHERE fact_inventory_distributor.tenant_id = %(tid_1)s::VARCHAR GROUP BY fact_inventory_distributor.distributor_id, fact_inventory_distributor.product_id) AS anon_1 ON fact_inbound_shipment.distributor_id = anon_1.distributor_id AND fact_inbound_shipment.product_id = anon_1.product_id AND fact_inbound_shipment.pod_date IS NOT NULL AND fact_inbound_shipment.pod_date > anon_1.snapshot_date AND lower(fact_inbound_shipment.line_state) = %(lower_1)s::VARCHAR 
WHERE fact_inbound_shipment.tenant_id = %(tid_1)s::VARCHAR GROUP BY fact_inbound_shipment.distributor_id, fact_inbound_shipment.product_id) AS land_since ON land_since.distributor_id = inv_latest.distributor_id AND land_since.product_id = inv_latest.product_id
